import{_ as r,a0 as l,w as p,s as d,I as t,x as n,a1 as i,A as a,ao as m}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const S=JSON.parse('{"title":"如何在RedHat/CentOS 7.x中使用nmcli管理网络 | LCTT x X-CMD","titleTemplate":false,"description":"如何在RedHat/CentOS 7.x中使用nmcli管理网络 | LCTT (201502) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在RedHat/CentOS 7.x中使用nmcli管理网络 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在RedHat/CentOS 7.x中使用nmcli管理网络 | LCTT (201502) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201502/20150114 How to Manage Network using nmcli Tool in RedHat or CentOS 7.x","title":"如何在RedHat/CentOS 7.x中使用nmcli管理网络","tag":"201502","desc":""},"relativePath":"201502/20150114 How to Manage Network using nmcli Tool in RedHat or CentOS 7.x.md","filePath":"[post].md"}'),s={name:"201502/20150114 How to Manage Network using nmcli Tool in RedHat or CentOS 7.x.md"};function c(C,e,g,u,T,x){const o=l("Link");return p(),d("div",null,[e[19]||(e[19]=t("h1",{id:"如何在redhat-centos-7-x中使用nmcli管理网络",tabindex:"-1"},[n("如何在RedHat/CentOS 7.x中使用nmcli管理网络 "),t("a",{class:"header-anchor",href:"#如何在redhat-centos-7-x中使用nmcli管理网络","aria-label":"Permalink to “如何在RedHat/CentOS 7.x中使用nmcli管理网络”"},"​")],-1)),t("p",null,[i(o,{href:"https://access.redhat.com/documentation/en-US/Red_Hat_Enterprise_Linux/7/html/7.0_Release_Notes/"},{default:a(()=>[...e[0]||(e[0]=[t("strong",null,"Red Hat Enterprise Linux 7",-1)])]),_:1}),e[1]||(e[1]=n("和",-1)),e[2]||(e[2]=t("strong",null,"CentOS 7",-1)),e[3]||(e[3]=n("的一个新特性是默认的网络服务由",-1)),e[4]||(e[4]=t("strong",null,"NetworkManager",-1)),e[5]||(e[5]=n("提供，这是一个动态的网络控制和配置守护进程，它在网络设备和连接可用时保持链接正常，同时也提供了典型的ifcfg类型的配置文件。NetworkManager可以用于下面这些连接：Ethernet、 VLANs、桥接、Bonds、Teams、 Wi-Fi、 移动宽带 (比如 3G)和IP-over-InfiniBand(IPoIB)。",-1))]),e[20]||(e[20]=m(`<p>NetworkManager可以由命令行工具<strong>nmcli</strong>控制。</p><h3 id="nmcli的通常用法" tabindex="-1">nmcli的通常用法 <a class="header-anchor" href="#nmcli的通常用法" aria-label="Permalink to “nmcli的通常用法”">​</a></h3><p>nmcli的通常语法是：</p><pre><code># nmcli [ OPTIONS ] OBJECT { COMMAND | help }
</code></pre><p>一件很酷的事情是你可以使用tab键来补全操作，这样你在何时忘记了语法你都可以按下tab来看到可用的选项了。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2014/12/nmcli-tab.jpg" alt="nmcli tab"></p><p>nmcli通常用法的一些例子：</p><pre><code># nmcli general status
</code></pre><p>会显示NetworkManager的整体状态。</p><pre><code># nmcli connection show
</code></pre><p>会显示所有的连接</p><pre><code># nmcli connection show -a
</code></pre><p>仅显示活跃的连接</p><pre><code># nmcli device status
</code></pre><p>显示NetworkManager识别的设备列表和它们当前的状态。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2014/12/nmcli-gneral.jpg" alt="nmcli general"></p><h3 id="启动-停止网络设备" tabindex="-1">启动/停止网络设备 <a class="header-anchor" href="#启动-停止网络设备" aria-label="Permalink to “启动/停止网络设备”">​</a></h3><p>你可以使用nmcli从命令行启动或者停止网络设备，这等同于ifconfig中的up和down。</p><p>停止网络设备使用下面的语法：</p><pre><code># nmcli device disconnect eno16777736
</code></pre><p>要启动它使用下面的语法：</p><pre><code># nmcli device connect eno16777736
</code></pre><h3 id="添加一个使用静态ip的以太网连接" tabindex="-1">添加一个使用静态IP的以太网连接 <a class="header-anchor" href="#添加一个使用静态ip的以太网连接" aria-label="Permalink to “添加一个使用静态IP的以太网连接”">​</a></h3><p>要用静态IP添加一个以太网连接可以使用下面的命令：</p><pre><code># nmcli connection add type ethernet con-name NAME_OF_CONNECTION ifname INTERFACE-NAME ip4 IP_ADDRESS gw4 GW_ADDRESS
</code></pre><p>将NAME_OF_CONNECTION替换成新的连接名（LCTT 译注：这个名字以后可以用来对其操作，可以使用任何简单明了的名称），INTERFACE-NAME 替换成你的接口名，IP_ADDRESS替换成你要的IP地址，GW_ADDRESS替换成你使用的网关地址（如果你并不使用网关，你可以忽略这部分）。</p><pre><code># nmcli connection add type ethernet con-name NEW_STATIC ifname eno16777736 ip4 192.168.1.141 gw4 192.168.1.1
</code></pre><p>要设置这个连接所使用的DNS服务器使用下面的命令：</p><pre><code># nmcli connection modify NEW_STATIC ipv4.dns &quot;8.8.8.8 8.8.4.4&quot;
</code></pre><p>要启用新的以太网连接，使用下面的命令：</p><pre><code># nmcli connection up NEW_STATIC ifname eno16777736
</code></pre><p>要查看新配置连接的详细信息，使用下面的命令：</p><pre><code># nmcli -p connection show NEW_STATIC
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2014/12/nmcli-add-static.jpg" alt="nmcli add static"></p><h3 id="添加一个使用dhcp的连接" tabindex="-1">添加一个使用DHCP的连接 <a class="header-anchor" href="#添加一个使用dhcp的连接" aria-label="Permalink to “添加一个使用DHCP的连接”">​</a></h3><p>如果你想要添加一个使用DHCP来配置接口IP地址、网关地址和dns服务器地址的新的连接，你要做的就是忽略上述命令中的ip/gw部分，NetworkManager会自动使用DHCP来获取配置细节。</p><p>比如，要创建一个新的叫NEW_DHCP的DHCP连接，在设备eno16777736上你可以使用下面的命令：</p><pre><code># nmcli connection add type ethernet con-name NEW_DHCP ifname eno16777736
</code></pre><hr>`,39)),t("p",null,[e[7]||(e[7]=n("via: ",-1)),i(o,{href:"http://linoxide.com/linux-command/nmcli-tool-red-hat-centos-7/"},{default:a(()=>[...e[6]||(e[6]=[n("http://linoxide.com/linux-command/nmcli-tool-red-hat-centos-7/",-1)])]),_:1})]),t("p",null,[e[11]||(e[11]=n("作者：",-1)),i(o,{href:"http://linoxide.com/author/adriand/"},{default:a(()=>[...e[8]||(e[8]=[n("Adrian Dinu",-1)])]),_:1}),e[12]||(e[12]=n(" 译者：",-1)),i(o,{href:"https://github.com/geekpi"},{default:a(()=>[...e[9]||(e[9]=[n("geekpi",-1)])]),_:1}),e[13]||(e[13]=n(" 校对：",-1)),i(o,{href:"https://github.com/wxy"},{default:a(()=>[...e[10]||(e[10]=[n("wxy",-1)])]),_:1})]),t("p",null,[e[16]||(e[16]=n("本文由 ",-1)),i(o,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...e[14]||(e[14]=[n("LCTT",-1)])]),_:1}),e[17]||(e[17]=n(" 原创翻译，",-1)),i(o,{href:"http://linux.cn/"},{default:a(()=>[...e[15]||(e[15]=[n("Linux中国",-1)])]),_:1}),e[18]||(e[18]=n(" 荣誉推出",-1))])])}const w=r(s,[["render",c]]);export{S as __pageData,w as default};
